let intermissionReadies = new Set();
function renderIntermissionReadyBox(){
  const box = document.getElementById("multiplayer-ready-status-box");
  const badge = document.getElementById("ready-count-badge");
  const chips = document.getElementById("ready-players-chips");
  const nextBtn = document.getElementById("btn-next-round");
  if(!Ni.currentLobby || !Ni.currentLobby.players){
    if(box) box.style.display = "none";
    if(nextBtn){ nextBtn.disabled = !1; nextBtn.style.opacity = "1"; }
    return;
  }
  if(box) box.style.display = "flex";
  const players = Object.values(Ni.currentLobby.players || {});
  const total = players.length;
  const readyCount = intermissionReadies.size;
  const allReady = (readyCount >= total && total > 0);
  if(badge){
    badge.textContent = allReady ? `✅ ALL ${total} PLAYERS READY!` : `⏳ ${readyCount} / ${total} Players Ready`;
    badge.style.color = allReady ? "var(--success)" : "var(--primary)";
  }
  const curUser = Dt.getUser();
  const isLocalReady = curUser && intermissionReadies.has(curUser.id);
  if(nextBtn){
    if(isLocalReady){
      nextBtn.innerHTML = `<span>✅ YOU ARE READY! (Waiting for ${total - readyCount} other${(total - readyCount) === 1 ? "" : "s"}...)</span>`;
      nextBtn.style.opacity = "0.75";
      nextBtn.disabled = !0;
    } else {
      nextBtn.innerHTML = `<span>✨ CLICK TO READY UP FOR NEXT TURN ➡️</span>`;
      nextBtn.style.opacity = "1";
      nextBtn.disabled = !1;
    }
  }
  if(chips){
    chips.innerHTML = "";
    players.forEach(p => {
      const isReady = intermissionReadies.has(p.user.id);
      const chip = document.createElement("div");
      chip.className = `player-ready-chip ${isReady ? "is-ready" : "waiting"}`;
      chip.innerHTML = `<span>${isReady ? "✅" : "⏳"}</span><span>${p.user.name}</span><span style="font-size:0.7rem; color:var(--text-muted);">(${isReady ? "Ready" : "Reviewing"})</span>`;
      chips.appendChild(chip);
    });
  }
  if(allReady && Ni.isHost()){
    setTimeout(() => {
      if(intermissionReadies.size >= total){
        intermissionReadies.clear();
        Ni.sendAction("NEXT_ROUND", { questionIndex: He.currentIndex + 1, activeTeamIndex: (He.activeTeamIndex + 1) % He.teams.length });
        qs();
        He.nextQuestion();
        He.isGameOver ? ZA() : Ud();
      }
    }, 600);
  }
}

